def format_invocation(name='', args=(), kwargs=None, **kw):
    if kwargs is None:
        kwargs = {}
    repr_func = kw.pop('repr', repr)
    if kw:
        raise TypeError('unexpected kwargs: %r' % list(kw.keys()))
    parts = [repr_func(a) for a in args]
    parts += ['%s=%s' % (k, repr_func(v)) for k, v in kwargs.items()]
    return '%s(%s)' % (name, ', '.join(parts))
```

