def _format_path(t_path):
    if not t_path:
        return 'Path()'
    # t_path is a sequence of (op, arg) pairs
    ops = list(zip(t_path[::2], t_path[1::2]))
    # Check if all ops are 'P' type (plain path parts)
    all_plain = all(op == 'P' for op, _ in ops)
    if all_plain:
        args = [bbrepr(arg) for _, arg in ops]
        return 'Path(%s)' % ', '.join(args)
    # Mixed path - need to reconstruct
    # Build a TType and use _format_t
    t = TType()
    t.__ops__ = (T,) + tuple(t_path)
    fmt = _format_t(t.__ops__[1:], T)
    if fmt.startswith('T'):
        return fmt
    return fmt
