def _format_t(path, root=T):
    root_str = {T: 'T', S: 'S', A: 'A'}.get(root, 'T')
    if not path:
        return root_str
    ops = list(zip(path[::2], path[1::2]))
    chunks = [root_str]
    for op, arg in ops:
        if op == '.':
            chunks.append('.%s' % arg)
        elif op == '[':
            if isinstance(arg, tuple) and len(arg) == 2 and all(isinstance(a, slice) or isinstance(a, int) for a in arg if not isinstance(a, slice)):
                inner = ', '.join(_format_slice(a) for a in arg)
                chunks.append('[%s]' % inner)
            elif isinstance(arg, tuple):
                inner = ', '.join(_format_slice(a) for a in arg)
                chunks.append('[%s]' % inner)
            elif isinstance(arg, slice):
                chunks.append('[%s]' % _format_slice(arg))
            else:
                chunks.append('[%s]' % bbrepr(arg))
        elif op == 'P':
            chunks.append('[%s]' % bbrepr(arg))
        elif op == '(':
            args, kwargs = arg
            parts = [bbrepr(a) for a in args]
            parts += ['%s=%s' % (k, bbrepr(v)) for k, v in kwargs.items()]
            chunks.append('(%s)' % ', '.join(parts))
        elif op == 'x':
            chunks.append('.__star__()')
        elif op == 'X':
            chunks.append('.__starstar__()')
        else:
            op_map = {'+': '+', '-': '-', '*': '*', '/': '/', '%': '%', ':': '**', '&': '&', '|': '|', '^': '^', '~': None, '_': None, '#': '//'}
            sym = op_map.get(op)
            if op in ('~', '_'):
                prefix = '~' if op == '~' else '-'
                chunks = ['%s(%s)' % (prefix, ''.join(chunks))]
            else:
                chunks = ['(%s %s %s)' % (''.join(chunks), sym, bbrepr(arg))]
    return ''.join(chunks)
